export function chapterEnding(report){if(report.config.expedition==='lockworks')return {title:report.won?'供能尽断，潮锁库台重归寂静。':'护库尚未肃清，先回岸重整。',image:'foundry-v71.png',text:'护壁的建立与解除来自本次实际机关状态；既有攻击和资源代价保留。'};if(report.config.expedition==='turncourt')return {title:report.won?'易相散尽，灯座复明。':'灯庭尚未清净，队伍先回岸重整。',image:'oathbreaker-v5.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2场；${report.party.filter(u=>u.hp>0).length}/6人生还。生命阶段不单独发奖，不回满或追加行动；仅按原普通金币经验结算。`,won:report.won};if(report.config.expedition==='beaconbridge')return {title:report.won?'灯桥上的巡声，终于换成归航的号角。':'巡灯尚未交接，队伍先回岸重整。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6人生还。正常领取后遗物先入仓库，仍须亲自分配/穿戴；已持有部件不自动激活套装。重复掉落不保证凑齐，三件心理弱点也保留。`,won:report.won};if(report.config.expedition==='trapworks')return {title:report.won?'机弦停止，闸庭归于安静。':'机廊仍在运转，队伍先退回岸边。',image:'foundry-v71.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。机关归零后才停止后续行动，已发生的射击与耗材保留；普通金币经验结算，无装备掉落。`,won:report.won};if(report.config.expedition==='ossuary')return {title:report.won?'雾影退去，各人的归途终于交汇。':'墓廊尚未清净，队伍先退回海岸。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6人仍有战斗能力。免疫不是抗性或可驱散护印，分清攻击类型和实际后备；正常领取金币与经验，无装备掉落。`,won:report.won};if(report.config.expedition==='breakwater')return {title:report.won?'潮堤接应完毕，信号随船回岸。':'潮堤仍有来人，队伍先回营准备。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 房；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。各房公开增援全部完成才算清场，单波没有独立房间收益；正常领取金币与经验，无装备掉落。`,won:report.won};if(report.config.expedition==='counterpoint')return {title:report.won?'回廊的迟声停下，自己的节奏还在。':'回廊仍有余拍，队伍先回营重配。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。迟拍只按下一回合真实队列计算，已附着效果不随来源倒下消失；正常领取金币与经验，无装备掉落。`,won:report.won};if(report.config.expedition==='confluence')return {title:report.won?'担架不再随军令同时抬起。':'药棚仍在换班，队伍先退回岸边。',image:'drowned-infirmary-v21.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。敌方群救按实际伤员和独立库存执行，击倒/禁疗不撤销已完成治疗；正常通关领取分诊铜签，再明确分配。`,won:report.won};if(report.config.expedition==='greenhouse')return {title:report.won?'浊芽合拢，清露还在瓶中。':'温室仍在浸蚀，队伍先退回栈桥。',image:'drowned-infirmary-v21.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。净化只能移除后续潮蚀，已发生的初击与跳伤保留；正常通关领取滤露面纱，再从仓库明确分配。`,won:report.won};if(report.config.expedition==='scriptorium')return {title:report.won?'旧印散去，书页仍在手中。':'裁室仍亮着灯，队伍先退出书库。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。破印只改变之后的效果状态，来源仍可重新施放；正常通关领取辨印晶镜，再从公会仓库明确分配。`,won:report.won};if(report.config.expedition==='palisade')return {title:report.won?'哨声渐息，双盾墙已露出缺口。':'哨声未停，队伍先退回栈桥外。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。援护来源倒下不能撤销既有检定，也不会退还已经支付的材料；正常通关结算可领取固定哨誓披甲。`,won:report.won};if(report.config.expedition==='inquest')return {title:report.won?'追问渐息，自己的心声仍然清楚。':'回声尚未散去，队伍先退出问堂。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。诘心回声不附着负面状态，净化不能撤销已经造成的心理伤害；正常结算可获得定心缎带。`,won:report.won};if(report.config.expedition==='shoals')return {title:report.won?'新的礁线，已能画进归航海图。':'这一段礁线，仍需重新准备。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。海图编号 ${report.config.shoalsChart||1}；正常领取通关结算后记入勘探册，每图不额外发放首通奖励。`,won:report.won};if(report.config.expedition==='theater')return {title:report.won?'合唱停下，队伍带着自己的声音归来。':'旧曲仍在回响，队伍先退回门厅。',image:'mirror-gallery-v9.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/2 场；${report.party.filter(u=>u.hp>0).length}/6 人仍有战斗能力。所有削弱与净化按战报结算，奖励须回营领取。`,won:report.won};if(report.config.expedition==='courier'){const crew=report.party.filter(u=>!u.owner&&report.config.heroes.some(h=>h.id===u.id)),standing=crew.filter(u=>u.hp>0),down=crew.filter(u=>u.hp<=0);return {title:report.won?(down.length?'船已靠岸，回信由同伴代交。':'信与同伴，一起抵岸。'):'邮路尚未打通，回信先留在营地。',image:'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${standing.length}/${crew.length} 位同行者仍有战斗能力。${down.length?'在远征中倒下的'+down.map(u=>u.name).join('、')+'随船回营。':'六人完整交接了这趟回信。'}余量：${report.supplies.herb}药草 / ${report.supplies.rune}符纸 / ${report.supplies.arrow}箭矢。${report.won?'回邮铜铃须正常领取后分配。':'可回营领取已通过房间的收益，本次没有通关额外奖励。'}`,won:report.won};}if(report.config.expedition==='foundrywatch')return {title:report.won?'最后一班守望交出了钥印。':'守望未散，队伍先退回外港。',image:'foundry-v71.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/3 场；${report.party.filter(u=>u.hp>0).length} 人存活。守望徽记须回营领取与分配。`,won:report.won};if(report.config.expedition==='foundry')return {title:report.won?'炉心归于沉寂，铸库重见海光。':'铸库仍在轰鸣，队伍暂退外港。',image:'foundry-v71.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/4 场；${report.party.filter(u=>u.hp>0).length} 人存活。余量：${report.supplies.herb}药草 / ${report.supplies.rune}符纸 / ${report.supplies.arrow}箭矢。装备与成长奖励请回营领取。`,won:report.won};if(!['chapter','harbor'].includes(report.config.expedition))return null;if(report.config.expedition==='harbor')return {title:report.won?'无光灯塔重新照亮盐风港。':'灯塔尚未点亮，远征队撤回海岸。',image:report.won?'harbor-seal-v41.png':'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/4 场；${report.party.filter(u=>u.hp>0).length} 人存活。路线：${report.rooms.map(r=>r.name).join(' → ')}。`,won:report.won};const alive=report.party.filter(u=>u.hp>0).length,cleared=report.rooms.filter(r=>r.won).length;return {title:report.won?(alive===6?'沉钟归于寂静，六人归航。':'沉钟归于寂静，有人未能归航。'):'远征止步，灯火仍在等待。',image:report.won?'last-lantern-v17.png':'abbey.png',text:`肃清 ${cleared}/${roomsFor(report.config).length} 场；${alive} 人存活。药草 ${report.supplies.herb}、符纸 ${report.supplies.rune}、箭矢 ${report.supplies.arrow}。`,won:report.won};}
